INSERT INTO blogs (id, slug, title, subtitle, excerpt, category_id, author_id,
                   content, content_text, reading_time_minutes, status, is_featured,
                   published_at, seo_title, seo_description, created_at, updated_at)
VALUES
  ('00000000-0000-4000-8000-00000000b101'::uuid, 'choosing-our-blanks', 'Choosing Our Blanks', 'The weight, the drape, the hand feel.', 'Why a garment starts with the fabric, not the print. A short note on the blanks we reach for again and again.',
   '00000000-0000-4000-8000-000000000a01'::uuid, '00000000-0000-4000-8000-000000000a02'::uuid,
   '[{"type":"paragraph","text":"A print can only be as good as the garment beneath it. We start with weight and drape, then check how a fabric settles after the first wash."},{"type":"heading","text":"Fewer, better blanks"},{"type":"paragraph","text":"Our core tee, hoodie and polo are deliberately uncomplicated: soft hand feel, a clean shoulder line, and enough structure to hold a small monogram."}]'::jsonb, 'A print can only be as good as the garment beneath it. We start with weight and drape, then check how a fabric settles after the first wash. Fewer, better blanks Our core tee, hoodie and polo are deliberately uncomplicated: soft hand feel, a clean shoulder line, and enough structure to hold a small monogram.', 2, 'published', false, now() - interval '3 days',
   'Choosing Our Blanks', 'Why a garment starts with the fabric, not the print. A short note on the blanks we reach for again and again.', now(), now()),
  ('00000000-0000-4000-8000-00000000b102'::uuid, 'printing-on-demand', 'Printing on Demand', 'Made after the order, never before.', 'What print to order changes about waste, lead time and the small details on a garment made just for you.',
   '00000000-0000-4000-8000-000000000a01'::uuid, '00000000-0000-4000-8000-000000000a02'::uuid,
   '[{"type":"paragraph","text":"Print to order means we do not guess a size or a colour months ahead. Your piece is made after you choose it."},{"type":"heading","text":"A slower kind of production"},{"type":"paragraph","text":"The trade-off is patience. In return, the garment is made for one person rather than a warehouse shelf."}]'::jsonb, 'Print to order means we do not guess a size or a colour months ahead. Your piece is made after you choose it. A slower kind of production The trade-off is patience. In return, the garment is made for one person rather than a warehouse shelf.', 2, 'published', false, now() - interval '2 days',
   'Printing on Demand', 'What print to order changes about waste, lead time and the small details on a garment made just for you.', now(), now()),
  ('00000000-0000-4000-8000-00000000b103'::uuid, 'a-weekend-in-linen', 'A Weekend in Linen', 'Notes from the studio wardrobe.', 'One shirt, a long weekend, and the small evidence of a fabric that gets better with wear.',
   '00000000-0000-4000-8000-000000000a01'::uuid, '00000000-0000-4000-8000-000000000a02'::uuid,
   '[{"type":"paragraph","text":"Linen is not a fabric for crisp perfection. It creases, it softens, and it settles into the shape of the day."},{"type":"heading","text":"Worn, not stored"},{"type":"paragraph","text":"We keep one linen piece in the studio purely to watch how it ages. Every weekend it looks a little more like its owner."}]'::jsonb, 'Linen is not a fabric for crisp perfection. It creases, it softens, and it settles into the shape of the day. Worn, not stored We keep one linen piece in the studio purely to watch how it ages. Every weekend it looks a little more like its owner.', 2, 'published', false, now() - interval '1 days',
   'A Weekend in Linen', 'One shirt, a long weekend, and the small evidence of a fabric that gets better with wear.', now(), now())
ON CONFLICT (slug) DO NOTHING;
